case class Vertex(id: Int, startX: Int, startY: Int, endX: Int, endY: Int)

class Vertices(tag: Tag) extends Table[Vertex](tag, "vertices") {
  def id = column[Int]("id", O.PrimaryKey)
  def x1 = column[Int]("x1"); def y1 = column[Int]("y1")
  def x2 = column[Int]("x2"); def y2 = column[Int]("y2")
  def * = (id, x1, y1, x2, y2) <> (Vertex.tupled, Vertex.unapply)
}
